const out = [];
function dump(n, depth){
  if(depth>3) return;
  const o = {id:n.id, name:n.name, type:n.type, w:Math.round(n.width), h:Math.round(n.height)};
  if(n.type==="TEXT"){ o.chars=n.characters; o.fontName=n.fontName; o.fontSize=n.fontSize; o.fills=n.fills&&n.fills[0]&&n.fills[0].color?("#"+Object.values(n.fills[0].color).map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join("")):null; }
  if("fills" in n && n.type!=="TEXT" && Array.isArray(n.fills) && n.fills.length){ o.fills=n.fills.map(f=>f.type==="SOLID"?("#"+Object.values(f.color).map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join("")):f.type); }
  if("cornerRadius" in n && n.cornerRadius) o.r=n.cornerRadius;
  if("children" in n){ o.kids=n.children.map(c=>{const r={id:c.id,name:c.name,type:c.type,w:Math.round(c.width),h:Math.round(c.height)}; if(c.type==="TEXT"){r.chars=c.characters;r.fontName=c.fontName;r.fontSize=c.fontSize;} if(Array.isArray(c.fills)&&c.fills.length&&c.fills[0].type==="SOLID"){r.fill="#"+Object.values(c.fills[0].color).map(v=>Math.round(v*255).toString(16).padStart(2,"0")).join("");} if(Array.isArray(c.fills)&&c.fills.length&&c.fills[0].type!=="SOLID"){r.fill=c.fills[0].type;} return r;}); }
  out.push({d:depth,...o});
  if("children" in n) n.children.forEach(c=>dump(c,depth+1));
}
